import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 79 By air","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 79 By air","description":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 时间、原因与让步从句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 78 The last one?","link":"/life/english/new-concept/book-2/unit-04/lesson-078"},"next":{"text":"第二册：实践与进步 · Lesson 80 The Crystal Palace","link":"/life/english/new-concept/book-2/unit-04/lesson-080"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 78 The last one?","link":"/life/english/new-concept/book-2/unit-04/lesson-078"},"next":{"text":"第二册：实践与进步 · Lesson 80 The Crystal Palace","link":"/life/english/new-concept/book-2/unit-04/lesson-080"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-079.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-079.md"}'),l={name:"life/english/new-concept/book-2/unit-04/lesson-079.md"};function o(s,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-79-by-air" tabindex="-1">第二册：实践与进步 · Lesson 79 By air <a class="header-anchor" href="#第二册-实践与进步-·-lesson-79-by-air" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 79 By air&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从飞机上欣赏风景也伴随延误和限制，体验需要兼顾过程与事实；练习原因和让步连接。本课的语言观察是：despite 后接名词或动名词，although 后接完整从句。两者都能引出不利条件，但结构不可直接替换。完成学习后，请写一段旅行体验，包含一个不便、一个值得欣赏的细节与一项限制。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>scenery</td><td>/ˈsiːnəri/</td><td>n.</td><td>风景</td><td>beautiful scenery</td></tr><tr><td>view</td><td>/vjuː/</td><td>n.</td><td>景色；看法</td><td>a clear view</td></tr><tr><td>seatbelt</td><td>/ˈsiːtbelt/</td><td>n.</td><td>安全带</td><td>fasten a seatbelt</td></tr><tr><td>departure</td><td>/dɪˈpɑːtʃə/</td><td>n.</td><td>出发</td><td>a delayed departure</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>despite the delay — 尽管延误，despite 后不加 of</li><li>look down at — 向下看某物</li></ul><h2 id="语法讲解-时间、原因与让步从句" tabindex="-1">语法讲解：时间、原因与让步从句 <a class="header-anchor" href="#语法讲解-时间、原因与让步从句" aria-label="Permalink to &quot;语法讲解：时间、原因与让步从句&quot;">​</a></h2><p>状语从句为主句提供时间、原因、条件或让步背景。连接词不仅连接形式，也表达逻辑：because 给原因，although 表示让步，while 可以表示同时或对照，until 标记持续的终点。英语通常不把 although 与 but、because 与 so 成对放在同一个复合句中。从句置前时一般用逗号隔开；选连接词前先判断两件事之间的实际关系。本课应用：despite 后接名词或动名词，although 后接完整从句。两者都能引出不利条件，但结构不可直接替换。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Despite the delay, we enjoyed the view from the plane.</p></blockquote><p>尽管航班延误，我们仍欣赏了飞机上的景色。</p><p>Despite the delay 是介词短语，主句 enjoyed 为过去式，from the plane 给出观察位置。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>despite it was late 结构不对；可用 despite the delay 或 although it was late。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>分组读 Despite the delay，注意 despite 不漏 /s/；重读 enjoyed 表转折后的重点。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Despite the delay, we enjoyed the view from the plane. Snow covered the mountains below. The seatbelt sign remained on until we reached smoother air.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一段旅行体验，包含一个不便、一个值得欣赏的细节与一项限制。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Despite the delay 是介词短语，主句 enjoyed 为过去式，from the plane 给出观察位置。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：despite it was late 结构不对；可用 despite the delay 或 although it was late。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选 despite/although：___ the delay, we enjoyed the view.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Despite</p><p><strong>解析：</strong> 后面是名词短语 the delay。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>安全带指示灯何时才熄灭？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> After the plane reached smoother air.</p><p><strong>解析：</strong> remained on until 表持续亮到空气较平稳时。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 although 改写 Despite the delay, we enjoyed the flight。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Although the flight was delayed, we enjoyed it.</p><p><strong>解析：</strong> although 后需完整从句，而不是单独名词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：时间、原因与让步从句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-078">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-080">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(l,[["render",o]]);export{u as __pageData,b as default};
